import{_ as e,o as a,c as r,ag as n}from"./chunks/framework.DGzMGr_a.js";const g=JSON.parse('{"title":"RO3 全球发行计划更新：国服2026年底，全球服推迟至2027年","description":"GRAVITY最新财报显示，仙境传说3国服预计2026年Q4上线，全球服调整至2027年发行，日本服由GungHo代理运营。","frontmatter":{"title":"RO3 全球发行计划更新：国服2026年底，全球服推迟至2027年","date":"2026-05-21T00:00:00.000Z","description":"GRAVITY最新财报显示，仙境传说3国服预计2026年Q4上线，全球服调整至2027年发行，日本服由GungHo代理运营。"},"headers":[],"relativePath":"news/release-schedule-202605.md","filePath":"news/release-schedule-202605.md","lastUpdated":1779362930000}'),o={name:"news/release-schedule-202605.md"};function l(d,t,i,s,h,u){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="ro3-全球发行计划更新-国服2026年底-全球服调整至2027年" tabindex="-1">RO3 全球发行计划更新：国服2026年底，全球服调整至2027年 <a class="header-anchor" href="#ro3-全球发行计划更新-国服2026年底-全球服调整至2027年" aria-label="Permalink to &quot;RO3 全球发行计划更新：国服2026年底，全球服调整至2027年&quot;">​</a></h1><p><strong>2026年5月21日</strong></p><h2 id="发行时间线调整" tabindex="-1">发行时间线调整 <a class="header-anchor" href="#发行时间线调整" aria-label="Permalink to &quot;发行时间线调整&quot;">​</a></h2><p>根据GRAVITY于2026年2月提交给美国证券交易委员会（SEC）的最新财报文件以及2025年Q4投资者简报，《仙境传说3》（RO3）的全球发行计划已做出重要调整：</p><table tabindex="0"><thead><tr><th>地区</th><th>预计上线时间</th><th>运营商</th></tr></thead><tbody><tr><td><strong>中国大陆</strong></td><td><strong>2026年第四季度</strong></td><td>上海热血网络（Rexue）</td></tr><tr><td><strong>全球服</strong></td><td><strong>2027年</strong></td><td>Gravity Game Vision / JoyMaker</td></tr><tr><td><strong>日本</strong></td><td>待公布（与全球服同步或稍晚）</td><td>GungHo Online Entertainment</td></tr><tr><td><strong>韩国/东南亚</strong></td><td>2027年</td><td>Gravity Game Vision</td></tr></tbody></table><h2 id="日本服代理确认" tabindex="-1">日本服代理确认 <a class="header-anchor" href="#日本服代理确认" aria-label="Permalink to &quot;日本服代理确认&quot;">​</a></h2><p>2026年2月13日，GungHo Online Entertainment（《智龙迷城》开发商、RO日本服运营商）正式宣布获得《RO仙境传说3》在日本地区的代理权。日本版本可能会与全球版本有所差异，由GungHo独立运营。</p><h2 id="全球服支持信息" tabindex="-1">全球服支持信息 <a class="header-anchor" href="#全球服支持信息" aria-label="Permalink to &quot;全球服支持信息&quot;">​</a></h2><ul><li><strong>服务器所在地</strong>：欧洲、美国、新加坡</li><li><strong>时区</strong>：GMT+8（北京时间）</li><li><strong>支持语言</strong>：简体中文、繁体中文、英语、韩语、日语、泰语、印尼语</li><li><strong>首发地区</strong>：台湾、香港、澳门、泰国、印尼、新加坡、马来西亚、菲律宾、韩国、日本</li></ul><h2 id="先锋测试回顾" tabindex="-1">先锋测试回顾 <a class="header-anchor" href="#先锋测试回顾" aria-label="Permalink to &quot;先锋测试回顾&quot;">​</a></h2><p>RO3于2025年8月进行了首次Pioneer Test（先锋测试），为限量不计费删档测试，仅限PC平台，覆盖东亚及东南亚地区。测试内容包括：</p><ul><li>六大职业基础技能与战斗</li><li>普隆德拉等经典场景3D重制</li><li>动态天气系统与昼夜循环</li><li>GVG公会战原型测试</li></ul><h2 id="后续展望" tabindex="-1">后续展望 <a class="header-anchor" href="#后续展望" aria-label="Permalink to &quot;后续展望&quot;">​</a></h2><p>虽然全球发行推迟至2027年，但国服有望在2026年底率先上线，这意味着中国玩家将最早体验到这个备受期待的RO正统续作。我们将持续关注国服测试进度，第一时间为大家带来最新资讯。</p>',14)])])}const p=e(o,[["render",l]]);export{g as __pageData,p as default};
